def count_negatives(grid):
    m, n = len(grid), len(grid[0])
    row, col = m - 1, 0                                                    # start at the bottom-left corner
    count = 0
    while row >= 0 and col < n:
        if grid[row][col] < 0:
            count += n - col                                                # every cell from col to n-1 in this row is also negative (row is non-increasing)
            row -= 1                                                       # move up to check the row above, at this same column
        else:
            col += 1                                                       # this cell isn't negative; search further right in this row
    return count


if __name__ == "__main__":
    grid = [[4, 3, 2, -1], [3, 2, 1, -1], [1, 1, -1, -2], [-1, -1, -2, -3]]
    print(count_negatives(grid))

